    allocator: Allocator,

    pub fn init(allocator: Allocator, vocab: []const []const u8, anchors: []const []const u8) !MGT
    pub fn deinit(self: *MGT) void
    pub fn encode(self: *MGT, text: []const u8, output: *std.ArrayList(u32)) !void
    pub fn decode(self: *MGT, tokens: []const u32, output: *std.ArrayList(u8)) !void
    pub fn vocabSize(self: *const MGT) usize
