#### Morfológiai Elemzés
```zig
const MorphemeType = enum {
    Prefix,
    Stem,
    Suffix,
    Standalone,
};

const Morpheme = struct {
    text: []const u8,
    type: MorphemeType,
    token_id: u32,
};

fn analyzeMorphology(self: *MGT, word: []const u8, allocator: Allocator) ![]Morpheme {
    var morphemes = std.ArrayList(Morpheme).init(allocator);

    const prefixes = [_][]const u8{ "meg", "el", "fel", "le", "ki", "be", "át" };
    const suffixes = [_][]const u8{ "nak", "nek", "ban", "ben", "hoz", "hez", "tól", "től" };

    var remaining = word;

    for (prefixes) |prefix| {
        if (std.mem.startsWith(u8, remaining, prefix)) {
            const token_id = self.token_to_id.get(prefix) orelse self.next_id;
            try morphemes.append(.{
                .text = prefix,
                .type = .Prefix,
                .token_id = token_id,
            });
            remaining = remaining[prefix.len..];
            break;
        }
    }

    var found_suffix = false;
    for (suffixes) |suffix| {
        if (std.mem.endsWith(u8, remaining, suffix)) {
            const stem_len = remaining.len - suffix.len;
            const stem = remaining[0..stem_len];

            const stem_id = self.token_to_id.get(stem) orelse self.next_id;
            try morphemes.append(.{
                .text = stem,
                .type = .Stem,
                .token_id = stem_id,
            });

            const suffix_id = self.token_to_id.get(suffix) orelse self.next_id + 1;
            try morphemes.append(.{
                .text = suffix,
                .type = .Suffix,
                .token_id = suffix_id,
            });

            found_suffix = true;
            break;
        }
    }

    if (!found_suffix and remaining.len > 0) {
        const token_id = self.token_to_id.get(remaining) orelse self.next_id;
        try morphemes.append(.{
            .text = remaining,
            .type = .Standalone,
            .token_id = token_id,
        });
    }

    return morphemes.toOwnedSlice();
}
```

**Magyar nyelvtan**: Prefix-tő-suffix dekompozíció (agglutináló nyelv)[github:kollarsandor/dontyoujuststop].

#### Anchor-based Segmentation
```zig
pub fn encode(self: *MGT, text: []const u8, output: *std.ArrayList(u32)) !void {
    var normalized = try self.normalize(text);
    defer self.allocator.free(normalized);

    var words = std.mem.tokenize(u8, normalized, " \t\n\r");

    while (words.next()) |word| {
        if (self.anchor_tokens.contains(word)) {
            const anchor_id = self.token_to_id.get(word).?;
            try output.append(anchor_id);
        } else {
            const morphemes = try self.analyzeMorphology(word, self.allocator);
            defer self.allocator.free(morphemes);

            for (morphemes) |morpheme| {
                if (self.token_to_id.get(morpheme.text)) |existing_id| {
                    try output.append(existing_id);
                } else {
                    try output.append(self.next_id);
                    try self.token_to_id.put(try self.allocator.dupe(u8, morpheme.text), self.next_id);
                    try self.id_to_token.put(self.next_id, morpheme.text);
                    self.next_id += 1;
                }
            }
        }
    }
}
```

**Anchor tokenek**: Kulcsfogalmak (pl. "mesterséges", "intelligencia") prioritált kezelése[github:kollarsandor/dontyoujuststop].

