#### Sequence Addition (Suffix Tree Build)
```zig
pub fn addSequence(self: *SSI, tokens: []const u32, doc_id: u64, is_anchor: bool) !void {
    if (tokens.len == 0) return;

    for (0..tokens.len) |start_idx| {
        var current = self.root;

        for (tokens[start_idx..]) |token| {
            if (current.children.get(token)) |child| {
                current = child;
                current.frequency += 1;
            } else {
                const new_node = try SSINode.init(self.allocator, token);
                try current.children.put(token, new_node);
                current = new_node;
                self.node_count += 1;
            }
        }

        current.is_leaf = true;
        current.doc_id = doc_id;
        current.is_anchor = is_anchor;
        self.leaf_count += 1;
    }
}
```

**Suffix fa építés**: Minden suffix hozzáadása O(n²) idő, O(n²) tár (optimalizálható Ukkonen algoritmussal)[github:kollarsandor/dontyoujuststop].

#### Top-K Retrieval
```zig
pub const Segment = struct {
    tokens: []u32,
    doc_id: u64,
    score: f32,
    is_anchor: bool,

    pub fn deinit(self: *Segment, allocator: Allocator) void {
        allocator.free(self.tokens);
    }
};

pub fn retrieveTopK(self: *SSI, query: []const u32, k: usize, allocator: Allocator) ![]Segment {
    var candidates = std.ArrayList(Segment).init(allocator);
    defer {
        for (candidates.items) |*seg| {
            if (candidates.items.len > k) seg.deinit(allocator);
        }
        candidates.deinit();
    }

    try self.collectCandidates(query, &candidates, allocator);

    for (candidates.items) |*candidate| {
        candidate.score = self.computeRelevance(query, candidate.tokens);
    }

    std.mem.sort(Segment, candidates.items, {}, struct {
        fn lessThan(_: void, a: Segment, b: Segment) bool {
            return a.score > b.score;
        }
    }.lessThan);

    const result_count = @min(k, candidates.items.len);
    const results = try allocator.alloc(Segment, result_count);

    for (0..result_count) |i| {
        results[i] = candidates.items[i];
    }

    return results;
}
```

**Relevancia számítás**:
```zig
fn computeRelevance(self: *SSI, query: []const u32, candidate: []const u32) f32 {
    var overlap_count: usize = 0;

    for (query) |q_token| {
        for (candidate) |c_token| {
            if (q_token == c_token) {
                overlap_count += 1;
                break;
            }
        }
    }

    const query_len_f: f32 = @floatFromInt(query.len);
    const cand_len_f: f32 = @floatFromInt(candidate.len);
    const overlap_f: f32 = @floatFromInt(overlap_count);

    const jaccard = overlap_f / (query_len_f + cand_len_f - overlap_f);

    return jaccard;
}
```

**Jaccard similarity**: Token halmazok átfedés / unió arány[github:kollarsandor/dontyoujuststop].

### F. Ranker (`ranker/ranker.zig` - 36KB)

**Filozófia**: N-gram + LSH (Locality-Sensitive Hashing) alapú pontozás[github:kollarsandor/dontyoujuststop].

#### Ranker Struktúra
```zig
pub const Ranker = struct {
    ngram_weights: []f32,
    lsh_hash_params: []u64,
    num_hash_functions: usize,
    seed: u64,
    allocator: Allocator,

    pub fn init(allocator: Allocator, ngram_size: usize, lsh_tables: usize, seed: u64) !Ranker
    pub fn deinit(self: *Ranker) void
    pub fn rankCandidates(self: *Ranker, candidates: []Segment, index: *SSI, allocator: Allocator) !void
};
```

#### N-gram Scoring
```zig
fn computeNgramScore(self: *Ranker, tokens: []const u32) f32 {
    if (tokens.len < 2) return 0.0;

    var total_score: f64 = 0.0;

    for (1..tokens.len) |i| {
        const bigram_hash = self.hashBigram(tokens[i - 1], tokens[i]);
        const weight_idx = @as(usize, @intCast(bigram_hash)) % self.ngram_weights.len;
        total_score += @as(f64, self.ngram_weights[weight_idx]);
    }

    if (tokens.len >= 3) {
        for (2..tokens.len) |i| {
            const trigram_hash = self.hashTrigram(tokens[i - 2], tokens[i - 1], tokens[i]);
            const weight_idx = @as(usize, @intCast(trigram_hash)) % self.ngram_weights.len;
            total_score += @as(f64, self.ngram_weights[weight_idx]) * 1.5;
        }
    }

    const len_f: f64 = @floatFromInt(tokens.len);
    return @floatCast(total_score / len_f);
}
```

**Hash függvények**:
```zig
fn hashBigram(self: *Ranker, t1: u32, t2: u32) u64 {
    var hasher = std.hash.Wyhash.init(self.seed);
    hasher.update(std.mem.asBytes(&t1));
    hasher.update(std.mem.asBytes(&t2));
    return hasher.final();
}

fn hashTrigram(self: *Ranker, t1: u32, t2: u32, t3: u32) u64 {
    var hasher = std.hash.Wyhash.init(self.seed);
    hasher.update(std.mem.asBytes(&t1));
    hasher.update(std.mem.asBytes(&t2));
    hasher.update(std.mem.asBytes(&t3));
    return hasher.final();
}
```

**Wyhash**: Gyors, nem-kriptográfiai hash (sebesség)[github:kollarsandor/dontyoujuststop].

#### LSH (Locality-Sensitive Hashing)
```zig
fn lshSignature(self: *Ranker, tokens: []const u32) []u64 {
    var signature = try self.allocator.alloc(u64, self.num_hash_functions);

    for (0..self.num_hash_functions) |h| {
        const hash_param = self.lsh_hash_params[h];
        var hash_val: u64 = 0;

        for (tokens) |token| {
            const token_u64: u64 = @intCast(token);
            hash_val ^= (token_u64 *% hash_param);
        }

        signature[h] = hash_val;
    }

    return signature;
}

fn lshSimilarity(sig1: []const u64, sig2: []const u64) f32 {
    var matches: usize = 0;

    for (0..sig1.len) |i| {
        if (sig1[i] == sig2[i]) {
            matches += 1;
        }
    }

    const len_f: f32 = @floatFromInt(sig1.len);
    const matches_f: f32 = @floatFromInt(matches);
    return matches_f / len_f;
}
```

**LSH elv**: Hasonló objektumok nagyobb valószínűséggel esnek ugyanabba a bucket-be (približatív nearest neighbor)[github:kollarsandor/dontyoujuststop].

#### Ranking Pipeline
```zig
pub fn rankCandidates(self: *Ranker, candidates: []Segment, index: *SSI, allocator: Allocator) !void {
    for (candidates) |*candidate| {
        const ngram_score = self.computeNgramScore(candidate.tokens);
        const frequency_score = self.computeFrequencyScore(candidate.tokens, index);
        const anchor_boost: f32 = if (candidate.is_anchor) 1.5 else 1.0;

        candidate.score = (ngram_score * 0.4 + frequency_score * 0.6) * anchor_boost;
    }
}

fn computeFrequencyScore(self: *Ranker, tokens: []const u32, index: *SSI) f32 {
    var total_freq: usize = 0;

    for (tokens) |token| {
        if (index.root.children.get(token)) |node| {
            total_freq += node.frequency;
        }
    }

    const len_f: f32 = @floatFromInt(@max(tokens.len, 1));
    const freq_f: f32 = @floatFromInt(total_freq);
    const normalized = freq_f / len_f;

    return std.math.log10(1.0 + normalized);
}
```

**Súlyozott kombinálás**: 40% n-gram, 60% frekvencia, anchor boost 1.5x[github:kollarsandor/dontyoujuststop].

