#### Propozíciós Logika
```zig
pub const PropositionType = enum {
    Atomic,
    And,
    Or,
    Not,
    Implies,
    ForAll,
    Exists,
};

pub const Proposition = struct {
    type: PropositionType,
    predicate: ?*const fn (context: *anyopaque) bool,
    left: ?*Proposition,
    right: ?*Proposition,
    variable: ?[]const u8,

    pub fn evaluate(self: *const Proposition, context: *anyopaque) bool {
        return switch (self.type) {
            .Atomic => if (self.predicate) |pred| pred(context) else false,
            .And => (self.left.?.evaluate(context) and self.right.?.evaluate(context)),
            .Or => (self.left.?.evaluate(context) or self.right.?.evaluate(context)),
            .Not => !self.left.?.evaluate(context),
            .Implies => !self.left.?.evaluate(context) or self.right.?.evaluate(context),
            .ForAll, .Exists => false,
        };
    }
};
```

**Logikai operátorok**: Teljes predikátum kalkulus (elsőrendű logika)[github:kollarsandor/dontyoujuststop].

#### Hoare Hármas
```zig
pub const HoareTriple = struct {
    precondition: *Proposition,
    operation: *Proposition,
    postcondition: *Proposition,

    pub fn verify(self: *const HoareTriple, context: *anyopaque) bool {
        if (!self.precondition.evaluate(context)) {
            return true;
        }

        if (!self.operation.evaluate(context)) {
            return false;
        }

        return self.postcondition.evaluate(context);
    }
};
```

**Hoare formula**: `{P} C {Q}` - Ha P igaz és C lefut, akkor Q igaz lesz[github:kollarsandor/dontyoujuststop].

