#### Invariants (Tudásgráf épség)
```zig
pub fn checkConnectivity(graph: *SelfSimilarRelationalGraph) bool {
    if (graph.nodes.count() == 0) return true;

    var visited = std.AutoHashMap(u64, void).init(graph.allocator);
    defer visited.deinit();

    const start_node = graph.nodes.valueIterator().next().?;
    var queue = std.ArrayList(*Node).init(graph.allocator);
    defer queue.deinit();

    queue.append(start_node) catch return false;
    visited.put(start_node.id, {}) catch return false;

    while (queue.items.len > 0) {
        const current = queue.orderedRemove(0);

        for (current.edges.items) |edge| {
            const neighbor_id = if (edge.source == current.id) edge.target else edge.source;
            if (!visited.contains(neighbor_id)) {
                if (graph.nodes.get(neighbor_id)) |neighbor| {
                    visited.put(neighbor_id, {}) catch return false;
                    queue.append(neighbor) catch return false;
                }
            }
        }
    }

    return visited.count() == graph.nodes.count();
}

pub fn checkCoherence(graph: *SelfSimilarRelationalGraph) bool {
    var it = graph.edges.valueIterator();
    while (it.next()) |edge| {
        const source_exists = graph.nodes.contains(edge.source);
        const target_exists = graph.nodes.contains(edge.target);

        if (!source_exists or !target_exists) {
            return false;
        }

        if (graph.nodes.get(edge.source)) |source_node| {
            var found = false;
            for (source_node.edges.items) |node_edge| {
                if (node_edge.id == edge.id) {
                    found = true;
                    break;
                }
            }
            if (!found) return false;
        }
    }

    return true;
}

pub fn checkEntanglement(graph: *SelfSimilarRelationalGraph) bool {
    var it = graph.entanglement_matrix.iterator();
    while (it.next()) |entry| {
        const node_id = entry.key_ptr.*;
        const entangled_set = entry.value_ptr.*;

        if (!graph.nodes.contains(node_id)) {
            return false;
        }

        var eit = entangled_set.keyIterator();
        while (eit.next()) |entangled_id| {
            if (!graph.nodes.contains(entangled_id.*)) {
                return false;
            }
        }
    }

    return true;
}
```

**Invariánsok**:
1. **Connectivity**: Gráf összefüggő (nincs sziget)
2. **Coherence**: Minden él két létező csomópont között van
3. **Entanglement**: Minden összefonódott csomópont létezik[github:kollarsandor/dontyoujuststop]

