#### Hausdorff Dimenzió Számítás
```zig
pub fn computeFractalDimension(tree: *FractalTree) !f64 {
    var level_counts = try tree.allocator.alloc(usize, tree.max_depth + 1);
    defer tree.allocator.free(level_counts);
    @memset(level_counts, 0);

    try countNodesAtLevel(tree.root, level_counts);

    var log_counts = try tree.allocator.alloc(f64, tree.max_depth + 1);
    defer tree.allocator.free(log_counts);

    var log_scales = try tree.allocator.alloc(f64, tree.max_depth + 1);
    defer tree.allocator.free(log_scales);

    for (0..tree.max_depth + 1) |level| {
        const count_f: f64 = @floatFromInt(@max(level_counts[level], 1));
        log_counts[level] = std.math.log10(count_f);

        const scale: f64 = 1.0 / std.math.pow(f64, @floatFromInt(tree.base_branching_factor), @floatFromInt(level + 1));
        log_scales[level] = std.math.log10(scale);
    }

    var sum_xy: f64 = 0.0;
    var sum_x: f64 = 0.0;
    var sum_y: f64 = 0.0;
    var sum_x2: f64 = 0.0;
    const n: f64 = @floatFromInt(tree.max_depth + 1);

    for (0..tree.max_depth + 1) |i| {
        sum_xy += log_scales[i] * log_counts[i];
        sum_x += log_scales[i];
        sum_y += log_counts[i];
        sum_x2 += log_scales[i] * log_scales[i];
    }

    const slope = (n * sum_xy - sum_x * sum_y) / (n * sum_x2 - sum_x * sum_x);

    return -slope;
}

fn countNodesAtLevel(node: *FractalNode, counts: []usize) !void {
    counts[node.level] += 1;

    for (node.children.items) |child| {
        try countNodesAtLevel(child, counts);
    }
}
```

**Box-counting módszer**: N(ε) ∝ ε^(-D), ahol D a Hausdorff-dimenzió[github:kollarsandor/dontyoujuststop].

**Lineáris regresszió**: log(N) vs log(1/ε) meredeksége adja D-t

#### Self-Similar Index
```zig
pub const SelfSimilarIndex = struct {
    trees: std.ArrayList(FractalTree),
    dimension_cache: std.AutoHashMap(u64, f64),
    allocator: Allocator,

    pub fn init(allocator: Allocator) SelfSimilarIndex
    pub fn deinit(self: *SelfSimilarIndex) void
    pub fn addData(self: *SelfSimilarIndex, data: []const u8) !u64
    pub fn queryByDimension(self: *SelfSimilarIndex, target_dim: f64, tolerance: f64) ![]u64
};

pub fn addData(self: *SelfSimilarIndex, data: []const u8) !u64 {
    var best_tree: ?*FractalTree = null;
    var min_dimension_diff: f64 = std.math.inf(f64);

    for (self.trees.items) |*tree| {
        const tree_dim = try computeFractalDimension(tree);
        const local_dim = try computeLocalFractalDimension(data);
        const diff = std.math.fabs(tree_dim - local_dim);

        if (diff < min_dimension_diff) {
            min_dimension_diff = diff;
            best_tree = tree;
        }
    }

    if (best_tree == null or min_dimension_diff > 0.5) {
        var new_tree = try FractalTree.init(self.allocator, 10, 4);
        try self.trees.append(new_tree);
        best_tree = &self.trees.items[self.trees.items.len - 1];
    }

    const node_id = try best_tree.?.insert(data);
    const tree_dim = try computeFractalDimension(best_tree.?);
    try self.dimension_cache.put(node_id, tree_dim);

    return node_id;
}

fn computeLocalFractalDimension(data: []const u8) !f64 {
    if (data.len < 2) return 1.0;

    var char_counts = std.AutoHashMap(u8, usize).init(std.heap.page_allocator);
    defer char_counts.deinit();

    for (data) |char| {
        const count = char_counts.get(char) orelse 0;
        try char_counts.put(char, count + 1);
    }

    var entropy: f64 = 0.0;
    const total_f: f64 = @floatFromInt(data.len);

    var it = char_counts.valueIterator();
    while (it.next()) |count| {
        const p: f64 = @as(f64, @floatFromInt(count.*)) / total_f;
        if (p > 0.0) {
            entropy -= p * std.math.log2(p);
        }
    }

    const max_entropy = std.math.log2(@as(f64, @floatFromInt(char_counts.count())));
    const normalized_entropy = if (max_entropy > 0.0) entropy / max_entropy else 0.0;

    return 1.0 + normalized_entropy;
}
```

**Adaptív indexelés**: Az adat "érdessége" (entrópia) alapján választ fraktálfát[github:kollarsandor/dontyoujuststop].

