#### Preferential Attachment (Barabási-Albert)
```zig
pub fn addNodeWithPreferentialAttachment(self: *SSRG, data: []const u8, embedding: []const f32, m: usize) !u64 {
    const new_node_id = try self.addNode(data, embedding);

    if (self.nodes.count() == 1) {
        return new_node_id;
    }

    var degrees = try self.allocator.alloc(usize, self.nodes.count() - 1);
    defer self.allocator.free(degrees);

    var node_ids = try self.allocator.alloc(u64, self.nodes.count() - 1);
    defer self.allocator.free(node_ids);

    var total_degree: usize = 0;
    var idx: usize = 0;
    var it = self.nodes.iterator();
    while (it.next()) |entry| {
        if (entry.key_ptr.* != new_node_id) {
            const degree = entry.value_ptr.*.edges.items.len;
            degrees[idx] = degree;
            node_ids[idx] = entry.key_ptr.*;
            total_degree += degree;
            idx += 1;
        }
    }

    if (total_degree == 0) {
        for (0..@min(m, node_ids.len)) |i| {
            _ = try self.addEdge(new_node_id, node_ids[i], 1.0, "preferential");
        }
        return new_node_id;
    }

    var connected = std.AutoHashMap(u64, void).init(self.allocator);
    defer connected.deinit();

    var prng = std.rand.DefaultPrng.init(@intCast(std.time.milliTimestamp()));
    const random = prng.random();

    while (connected.count() < @min(m, node_ids.len)) {
        const rand_val = random.uintLessThan(usize, total_degree);
        var cumulative: usize = 0;

        for (0..node_ids.len) |i| {
            cumulative += degrees[i];
            if (rand_val < cumulative and !connected.contains(node_ids[i])) {
                _ = try self.addEdge(new_node_id, node_ids[i], 1.0, "preferential");
                try connected.put(node_ids[i], {});
                break;
            }
        }
    }

    return new_node_id;
}
```

**Skálafüggetlen hálózat**: P(k) ∝ k^(-γ) fokszámeloszlás (sok kis node, kevés hub)[github:kollarsandor/dontyoujuststop].

#### Community Detection (Louvain-módszer)
```zig
pub fn detectCommunities(self: *SSRG, allocator: Allocator) !std.AutoHashMap(u64, u64) {
    var communities = std.AutoHashMap(u64, u64).init(allocator);

    var it = self.nodes.keyIterator();
    while (it.next()) |node_id| {
        try communities.put(node_id.*, node_id.*);
    }

    var improved = true;
    var iteration: usize = 0;
    const MAX_ITERATIONS: usize = 100;

    while (improved and iteration < MAX_ITERATIONS) {
        improved = false;
        iteration += 1;

        var node_it = self.nodes.iterator();
        while (node_it.next()) |entry| {
            const node_id = entry.key_ptr.*;
            const current_community = communities.get(node_id).?;

            var neighbor_communities = std.AutoHashMap(u64, f32).init(allocator);
            defer neighbor_communities.deinit();

            for (entry.value_ptr.*.edges.items) |edge| {
                const neighbor_id = if (edge.source == node_id) edge.target else edge.source;
                const neighbor_community = communities.get(neighbor_id).?;

                const current_weight = neighbor_communities.get(neighbor_community) orelse 0.0;
                try neighbor_communities.put(neighbor_community, current_weight + edge.weight);
            }

            var best_community = current_community;
            var best_modularity: f32 = 0.0;

            var comm_it = neighbor_communities.iterator();
            while (comm_it.next()) |comm_entry| {
                const modularity = comm_entry.value_ptr.*;
                if (modularity > best_modularity) {
                    best_modularity = modularity;
                    best_community = comm_entry.key_ptr.*;
                }
            }

            if (best_community != current_community) {
                try communities.put(node_id, best_community);
                improved = true;
            }
        }
    }

    return communities;
}
```

**Modularitás optimalizálás**: Klaszterek keresése Q = Σ[A_ij - k_i*k_j/(2m)] δ(c_i, c_j) maximalizálásával[github:kollarsandor/dontyoujuststop].

