#### NCCL AllReduce
```zig
pub fn allReduceGradients(self: *DistributedTrainer) !void {
    if (self.nccl_comm == null) return;

    var all_gradients = std.ArrayList(f32).init(self.allocator);
    defer all_gradients.deinit();

    for (self.local_model.layers) |*layer| {
        try all_gradients.appendSlice(layer.s_weight.data);
        try all_gradients.appendSlice(layer.t_weight.data);
        try all_gradients.appendSlice(layer.s_bias.data);
        try all_gradients.appendSlice(layer.t_bias.data);
    }

    const count = all_gradients.items.len;
    const result = nccl.ncclAllReduce(
        all_gradients.items.ptr,
        all_gradients.items.ptr,
        count,
        nccl.ncclFloat,
        nccl.ncclSum,
        self.nccl_comm.?,
        null
    );

    if (result != nccl.ncclSuccess) {
        return error.NCCLAllReduceFailed;
    }

    const world_size_f: f32 = @floatFromInt(self.world_size);
    for (all_gradients.items) |*grad| {
        grad.* /= world_size_f;
    }

    var offset: usize = 0;
    for (self.local_model.layers) |*layer| {
        const s_weight_size = layer.s_weight.data.len;
        @memcpy(layer.s_weight.data, all_gradients.items[offset..offset + s_weight_size]);
        offset += s_weight_size;

        const t_weight_size = layer.t_weight.data.len;
        @memcpy(layer.t_weight.data, all_gradients.items[offset..offset + t_weight_size]);
        offset += t_weight_size;

        const s_bias_size = layer.s_bias.data.len;
        @memcpy(layer.s_bias.data, all_gradients.items[offset..offset + s_bias_size]);
        offset += s_bias_size;

        const t_bias_size = layer.t_bias.data.len;
        @memcpy(layer.t_bias.data, all_gradients.items[offset..offset + t_bias_size]);
        offset += t_bias_size;
    }
}
```

**Ring-AllReduce**: NCCL optimalizált kollektív kommunikáció (bandwidth optimal)[github:kollarsandor/dontyoujuststop].

#### Gradient Aggregation
```zig
pub fn trainStep(self: *DistributedTrainer, batch: []TrainingSample) !f32 {
    var total_loss: f64 = 0.0;

    for (batch) |sample| {
        const tensor_dim = std.math.mul(usize, self.local_model.dim, 2) catch continue;
        var input = try Tensor.init(self.allocator, &.{1, tensor_dim});
        defer input.deinit();

        try createEmbeddingInPlace(&input, sample.tokens, 1000, self.local_model.dim);

        try self.local_model.forward(&input);

        var sum: f64 = 0.0;
        for (input.data) |v| {
            if (!std.math.isNan(v) and !std.math.isInf(v)) {
                sum += @as(f64, v);
            }
        }
        const avg = sum / @as(f64, @floatFromInt(@max(input.data.len, 1)));
        total_loss += avg * avg;
    }

    try self.allReduceGradients();

    var gradients = try self.computeGradients();
    defer gradients.deinit();

    var params = try self.getFlattenedParams();
    defer params.deinit();

    try self.optimizer.update(&gradients, &params, 0.001);

    try self.applyFlattenedParams(&params);

    const batch_loss: f32 = @floatCast(total_loss / @as(f64, @floatFromInt(@max(batch.len, 1))));
    return batch_loss;
}
```

