**Kvantum Szimuláció GPU-n**:
```futhark
entry rgpu_hadamard [n] (state: [n]complex) : [n]complex =
    let h00 = 1.0 / f32.sqrt(2.0)
    let h01 = 1.0 / f32.sqrt(2.0)
    let h10 = 1.0 / f32.sqrt(2.0)
    let h11 = -1.0 / f32.sqrt(2.0)
    in map (\i -> 
        if i % 2 == 0
        then complex.add (complex.scale h00 state[i]) (complex.scale h01 state[i+1])
        else complex.add (complex.scale h10 state[i-1]) (complex.scale h11 state[i])
    ) (iota n)
