uint16_t f32_to_f16(float val) {
    uint32_t bits = *(uint32_t*)&val;
    uint32_t sign = (bits >> 16) & 0x8000;
    uint32_t exp = ((bits >> 23) & 0xFF) - 112;
    uint32_t mant = (bits >> 13) & 0x3FF;
    return (uint16_t)(sign | (exp << 10) | mant);
}
